#!/usr/bin/env python3
"""Export non-commercial publication evidence: metadata, hashes and reproduction bindings only."""
import argparse,json,hashlib,gzip,datetime,collections,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];sha=lambda b:hashlib.sha256(b).hexdigest()
ap=argparse.ArgumentParser();ap.add_argument('recordings',nargs='+',type=Path);ap.add_argument('--output',type=Path,default=ROOT/'artifacts/full-videos');a=ap.parse_args();a.output.mkdir(parents=True,exist_ok=True)
for path in a.recordings:
 path=path.resolve();r=json.loads((path/'recording.json').read_text());v=json.loads((path/'verification.json').read_text());u=json.loads((path/'ui-verification.json').read_text());media=json.loads((path/'media.json').read_text());rollback=json.loads((path/'rollback.json').read_text());assert r['pass'] and v['pass_'] and u['pass_'] and media['pass_'] and rollback['pass'];m=r['identity']['map'];dest=a.output/f'E1M{m}';dest.mkdir(exist_ok=True)
 manifest=dict(schemaVersion=1,map=m,scope='Final EVM presentation frames and independently native-verified finite pixels; metadata contains no commercial asset pixels.',identity=r['identity'],startedUTC=r['startedUTC'],endedUTC=r['endedUTC'],counts={k:r[k] for k in ['gameplayTics','gameplayFrames','gameplayCaptures','menuFrames','wipeFrames','intermissionFrames','finaleFrames','demoTics','continuationTics','nativeGameplayComparisons','totalVideoFrames'] if k in r},frames=[{k:f[k] for k in ['frameId','kind','demoTic','gameplayTic','rng','state','stage','count','sha256','paletteSha256','paletteBank','transactionHash','virtualSamples']} for f in r['frames']],transactions=r['transactions'],gas=r['totalGas'],rpcSeconds=r['rpcSeconds'],nativeSummary={k:x for k,x in v.items() if k!='gameplay'},nativeUI={k:x for k,x in u.items() if k!='frames'},media=media,rollback=rollback,localEvidence=[dict(file=str(p.relative_to(ROOT)),sha256=sha(p.read_bytes()),bytes=p.stat().st_size) for p in [path/'recording.json',path/'verification.json',path/'ui-verification.json',path/'media.json',path/'rollback.json',Path(media['path'])]])
 manifest.update(checkpointLineage=r.get('checkpointLineage'),presentationPolicy=r.get('presentationPolicy'),postExitInputs=r.get('postExitInputs'),originalTapeConsumedTics=r.get('originalTapeConsumedTics'),originalTapePreservedTotalTics=r.get('originalTapePreservedTotalTics'))
