 (dest/'virtual-samples.json').write_text(json.dumps([dict(frameId=f['frameId'],gameplayTic=f['gameplayTic'],samples=f['virtualSamples']) for f in r['frames'] if f['virtualSamples']],indent=2)+'\n')
 (dest/'checks.json').write_text(json.dumps(dict(pass_=True,nativeGameplay=v,nativeUI={k:x for k,x in u.items() if k!='frames'},rollback=rollback,media=media),indent=2)+'\n')
